async function detectSubjectLayerId(doc,bounds){try{if(!doc||!bounds||!doc.layers||!doc.layers.length)return null;if(doc.layers.length===1&&doc.layers[0].kind!==constants.LayerKind?.GROUP)return null;const pad=Math.max(16,Math.round(Math.min(bounds.right-bounds.left,bounds.bottom-bounds.top)*0.12));const testBounds={left:Math.max(0,bounds.left-pad),top:Math.max(0,bounds.top-pad),right:Math.min(doc.width,bounds.right+pad),bottom:Math.min(doc.height,bounds.bottom+pad)};let scanLayers=Array.from(doc.layers);for(let depth=0;depth<3;depth++){const vis=scanLayers.filter(l=>l&&l.visible!==false&&!l.isBackgroundLayer);const hasBg=scanLayers.some(l=>l&&l.visible!==false&&l.isBackgroundLayer);if(vis.length===1&&vis[0].kind===constants.LayerKind?.GROUP){const cls=await classifyLayerForSubject(doc,vis[0],testBounds);if(cls.role==="container"||!hasBg){const inner=Array.from(vis[0].layers||[]);if(inner.length>1){scanLayers=inner;continue}}}break}if(scanLayers.length<=1)return null;let subject=null;let subjectBounds=null;const selH=Math.max(16,bounds.bottom-bounds.top);for(const l of scanLayers){const info=await classifyLayerForSubject(doc,l,testBounds);if(info.role==="skip"||info.role==="miss")continue;if(info.role==="backdrop")break;if(info.role==="cutout"){if(!subject){subject=l;subjectBounds=info.bounds;continue}const nextH=info.bounds.bottom-info.bounds.top;const sameStandingScale=nextH>=selH*1.35&&(subjectBounds.bottom-subjectBounds.top)>=selH*1.35;const lowOverlapX=rectOverlapRatioX(subjectBounds,info.bounds)<0.45;if(sameStandingScale&&lowOverlapX){subject=l;subjectBounds=info.bounds}else{break}}}return subject?subject.id:null}catch(e){console.warn("Could not detect cutout subject layer for grounding:",e)}return null}
