function buildShadowMultiplyBuffer(origData,origComp,genData,genComp,w,h,genW,genH,selRect=null){const out=new Uint8Array(w*h*4);const{gainR,gainG,gainB}=sampleChannelGain(origData,origComp,genData,genComp,w,h,genW,genH,selRect);const noiseFloor=5.5;const relStart=0.045;const relFull=0.20;for(let y=0;y<h;y++){const gy=genH===h?y:Math.min(genH-1,Math.floor(y*genH/h));for(let x=0;x<w;x++){const gx=genW===w?x:Math.min(genW-1,Math.floor(x*genW/w));const oi=(y*w+x)*origComp;const gi=(gy*genW+gx)*genComp;const di=(y*w+x)*4;if(origComp>=4&&origData[oi+3]<8){out[di]=255;out[di+1]=255;out[di+2]=255;out[di+3]=0;continue}const ro=origData[oi],go=origData[oi+1],bo=origData[oi+2];const rg=genData[gi]/gainR,gg=genData[gi+1]/gainG,bg=genData[gi+2]/gainB;const lumO=0.299*ro+0.587*go+0.114*bo;const lumG=0.299*rg+0.587*gg+0.114*bg;const darkening=lumO-lumG;const relDark=darkening/Math.max(lumO,28);if(darkening<=noiseFloor||relDark<=relStart){out[di]=255;out[di+1]=255;out[di+2]=255;out[di+3]=0;continue}const u=Math.min(1,Math.max(0,(relDark-relStart)/(relFull-relStart)));const t=u*u*(3-2*u);const lumRatio=Math.min(1,Math.max(0,lumG/Math.max(lumO,12)));const rRatio=Math.min(1,Math.max(0,rg/Math.max(ro,20)));const gRatio=Math.min(1,Math.max(0,gg/Math.max(go,20)));const bRatio=Math.min(1,Math.max(0,bg/Math.max(bo,20)));out[di]=Math.min(255,Math.max(0,Math.round(255*(0.86*lumRatio+0.14*rRatio))));out[di+1]=Math.min(255,Math.max(0,Math.round(255*(0.86*lumRatio+0.14*gRatio))));out[di+2]=Math.min(255,Math.max(0,Math.round(255*(0.86*lumRatio+0.14*bRatio))));out[di+3]=Math.min(255,Math.max(1,Math.round(t*255)))}}return out}
async function extractLayerPixelsViaTempDoc(fileObj,placedBounds,origSnap,destDoc){let tmpFile=null,tmpDoc=null;try{const ext=getImageFileExtension(fileObj.arrayBuffer,fileObj.contentType);const folder=await storage.localFileSystem.getTemporaryFolder();placedFileSequence+=1;tmpFile=await folder.createFile(`tempShadow_${Date.now()}_${placedFileSequence}.${ext}`,{overwrite:true});await tmpFile.write(fileObj.arrayBuffer,{format:storage.formats.binary});tmpDoc=await app.open(tmpFile);if(!tmpDoc)throw new Error("Could not open generated shadow image.");const rawPbW=Math.max(2,placedBounds.right-placedBounds.left);const rawPbH=Math.max(2,placedBounds.bottom-placedBounds.top);const obW=Math.max(1,origSnap.bounds.right-origSnap.bounds.left);const obH=Math.max(1,origSnap.bounds.bottom-origSnap.bounds.top);const sx=origSnap.w/obW,sy=origSnap.h/obH;const pbW=Math.max(origSnap.w,Math.round(rawPbW*sx));const pbH=Math.max(origSnap.h,Math.round(rawPbH*sy));if(tmpDoc.width!==pbW||tmpDoc.height!==pbH){await tmpDoc.resizeImage(pbW,pbH)}const cropL=Math.max(0,Math.min(pbW-origSnap.w,Math.round((origSnap.bounds.left-placedBounds.left)*sx)));const cropT=Math.max(0,Math.min(pbH-origSnap.h,Math.round((origSnap.bounds.top-placedBounds.top)*sy)));const cropR=Math.min(pbW,cropL+origSnap.w);const cropB=Math.min(pbH,cropT+origSnap.h);const res=await imaging.getPixels({documentID:tmpDoc.id,applyAlpha:true,sourceBounds:{left:cropL,top:cropT,right:cropR,bottom:cropB},targetSize:{width:origSnap.w,height:origSnap.h},colorSpace:"RGB",colorProfile:"sRGB IEC61966-2.1",componentSize:8});try{return{genRaw:await res.imageData.getData(),genW:res.imageData.width,genH:res.imageData.height,genComp:res.imageData.components||4}}finally{try{res.imageData.dispose()}catch(e){}}}finally{if(tmpDoc){try{await tmpDoc.closeWithoutSaving()}catch(e){}}try{if(destDoc&&app.activeDocument?.id!==destDoc.id)app.activeDocument=destDoc}catch(e){}if(tmpFile){try{await tmpFile.delete()}catch(e){}}}}
async function addRevealSelectionMask(e){const{selectionBounds:t,selectionImageData:a,captureBounds:cap,shadowMode:sm,docWidth:dw,docHeight:dh}=e;await imaging.putSelection({imageData:a,targetBounds:{left:t.left,top:t.top},commandName:"reselect"});const n=nanoBananaGeometry.revealFeatherRadius(t);if(n>0){let contractPx=sm?0:n*REVEAL_CONTRACT_FACTOR;if(!sm&&cap){const margins=[];if(t.left>0)margins.push(Math.max(0,t.left-cap.left));if(t.top>0)margins.push(Math.max(0,t.top-cap.top));if(!dw||t.right<dw)margins.push(Math.max(0,cap.right-t.right));if(!dh||t.bottom<dh)margins.push(Math.max(0,cap.bottom-t.bottom));const margin=margins.length?Math.min(...margins):n;if(margin>=n){contractPx=0}else{contractPx=Math.max(0,Math.ceil(n-margin)+1)}}const steps=[];if(contractPx>0){steps.push({"_obj":"contract","by":{"_unit":"pixelsUnit","_value":contractPx},"_options":{"dialogOptions":"dontDisplay"}})}steps.push({"_obj":"feather","radius":{"_unit":"pixelsUnit","_value":n},"_options":{"dialogOptions":"dontDisplay"}});await action.batchPlay(steps,{})}await action.batchPlay([{"_obj":"make","at":{"_enum":"channel","_ref":"channel","_value":"mask"},"new":{"_class":"channel"},"using":{"_enum":"userMaskEnabled","_value":"revealSelection"}}],{})}
